1	//! Named-type resolution index — interfaces, type aliases, and their declared
2	//! generic type parameters, indexed for fast `(file, name)` lookup.
3	//!
4	//! Built once from `GlobalSourceData` before parallel resolution starts,
5	//! mirroring `import_map.rs::ImportResolutionMap`'s split: `GlobalSourceData`'s
6	//! own maps stay flat (`FxHashMap<String, T>`, unchanged — `merge()` and the
7	//! resolver test module's fixture-building code both depend on that shape),
8	//! while this index restructures them into nested
9	//! `FxHashMap<Utf8PathBuf, FxHashMap<CompactString, T>>` maps so a lookup can
10	//! borrow `&Utf8Path`/`&str` directly instead of allocating a fresh
11	//! `"{file}:{name}"` String per call. `lookup_interface`/`lookup_type_alias`
12	//! (the two hottest of these) run recursively for every prop, every generic
13	//! argument, and every extends clause across the whole component tree — the
14	//! same cost `ImportResolutionMap` and `ResolutionContext::enum_bare_index`
15	//! were already built to eliminate for import/enum lookups elsewhere in this
16	//! resolver.
17	
18	use camino::{Utf8Path, Utf8PathBuf};
19	use compact_str::CompactString;
20	use rustc_hash::{FxHashMap, FxHashSet};
21	
22	use crate::path_key::PathKey;
23	
24	use crate::types::{
25	    CollectedInterface, CollectedType, CollectedTypeAlias, EnumValue, GlobalSourceData, SourceData, TypeName,
26	};
27	
28	/// The project's declarations. Shared behind an `Arc` so a lazy session's context rebuild, which sets a new
29	/// dependency `fallback`, copies a pointer and not every interface and alias of the project.
30	#[derive(Clone, Default)]
31	pub(crate) struct IndexMaps {
32	    interfaces: FxHashMap<PathKey, FxHashMap<CompactString, CollectedInterface>>,
33	    type_aliases: FxHashMap<PathKey, FxHashMap<CompactString, CollectedTypeAlias>>,
34	    type_alias_params: FxHashMap<PathKey, FxHashMap<CompactString, Vec<TypeName>>>,
35	    interface_type_params: FxHashMap<PathKey, FxHashMap<CompactString, Vec<TypeName>>>,
36	    /// Type parameter defaults of the aliases and interfaces above (`SourceData::type_param_defaults`).
37	    type_param_defaults: FxHashMap<PathKey, FxHashMap<CompactString, Vec<Option<CollectedType>>>>,
38	    /// The array-typed consts each file declares, by their literal members (`SourceData::const_arrays`): what
39	    /// `(typeof X)[number]` reads as the symbol `X` in scope in the file that wrote the type.
40	    const_arrays: FxHashMap<PathKey, FxHashMap<CompactString, Vec<EnumValue>>>,
41	    /// Files declaring `React.`-qualified names (`@types/react`), the only ones a qualified fallback can match.
42	    react_namespaced: FxHashSet<PathKey>,
43	}
44	
45	#[derive(Clone, Default)]
46	pub(crate) struct NamedTypeIndex {
47	    maps: std::sync::Arc<IndexMaps>,
48	    /// Loaded dependency declarations (ADR 0010), consulted for a file this index holds nothing for. Shared by every
49	    /// watch revision, never copied.
50	    pub(crate) fallback: Option<std::sync::Arc<NamedTypeIndex>>,
51	}
52	
53	impl std::ops::Deref for NamedTypeIndex {
54	    type Target = IndexMaps;
55	
56	    fn deref(&self) -> &IndexMaps {
57	        &self.maps
58	    }
59	}
60	
61	/// What `lookup_ambient` found at a given ambient lib file, mirroring the
62	/// two shapes a same-file/imported lookup can also produce.
63	pub(crate) enum AmbientMatch<'a> {
64	    Interface,
65	    TypeAlias(&'a CollectedTypeAlias),
66	}
67	
68	impl NamedTypeIndex {
69	    /// Build from a fully-merged `GlobalSourceData`. Called once per
70	    /// resolution pass (`ResolutionContext::build`), before parallel
71	    /// resolution starts. No I/O — pure data transformation.
72	    ///
73	    /// Splits each flat `"{file}:{name}"` key on its *last* `:` — the same
74	    /// technique `ResolutionContext::enum_bare_index`/`const_array_bare_index`
75	    /// already use — rather than requiring a value-embedded `file_path` to
76	    /// anchor the split, so this works uniformly across all four maps
77	    /// (`type_alias_params`/`interface_type_params`'s own values carry no
78	    /// `file_path` of their own to anchor on).
79	    pub(crate) fn build(global: &GlobalSourceData) -> Self {
80	        let mut index = Self::default();
81	        index.insert_flat_maps(
82	            &global.interfaces,
83	            &global.interface_type_params,
84	            &global.type_aliases,
85	            &global.type_alias_params,
86	            &global.type_param_defaults,
87	        );
88	        index.insert_const_arrays(&global.const_arrays);
89	        index
90	    }
91	
92	    /// Remove `file`'s entries from every map — mirrors
93	    /// `GlobalSourceData::remove_file`'s per-file semantics, so
94	    /// `WatchSession::update_file` can keep this index in sync incrementally
95	    /// instead of rebuilding the whole project's index (every interface and
96	    /// type alias, cloned again) on every single-file edit. Confirmed as a
97	    /// real, measured regression via `crates/core/benches/extraction.rs`'s
98	    /// `incremental_update` group before this existed — rebuilding via `build`
99	    /// there roughly doubled per-edit latency, since a full-project index
100	    /// rebuild wasn't amortized the way it is by `extract()`'s one-shot path
101	    /// (which resolves every component in one run, not just the few affected
102	    /// by a single edit).
103	    pub(crate) fn remove_file(&mut self, file: &Utf8Path) {
104	        let maps = std::sync::Arc::make_mut(&mut self.maps);
105	        maps.interfaces.remove(file.as_str());
106	        maps.type_aliases.remove(file.as_str());
107	        maps.type_alias_params.remove(file.as_str());
108	        maps.interface_type_params.remove(file.as_str());
109	        maps.type_param_defaults.remove(file.as_str());
110	        maps.const_arrays.remove(file.as_str());
111	        maps.react_namespaced.remove(file.as_str());
112	    }
113	
114	    /// Insert one freshly re-parsed file's own (not yet merged) interfaces/
115	    /// type aliases into this index — the incremental counterpart to `build`'s
116	    /// whole-project walk. Callers should `remove_file` first so a renamed or
117	    /// removed declaration doesn't linger under its old name.
118	    pub(crate) fn merge_file(&mut self, data: &SourceData) {
119	        self.insert_flat_maps(
120	            &data.interfaces,
121	            &data.interface_type_params,
122	            &data.type_aliases,
123	            &data.type_alias_params,
124	            &data.type_param_defaults,
125	        );
126	        self.insert_const_arrays(&data.const_arrays);
127	    }
128	
129	    /// Splits each flat `"{file}:{name}"` key on its *last* `:` — the same
130	    /// technique `ResolutionContext::enum_bare_index`/`const_array_bare_index`
131	    /// already use — rather than requiring a value-embedded `file_path` to
132	    /// anchor the split, so this works uniformly across all four maps
133	    /// (`type_alias_params`/`interface_type_params`'s own values carry no
134	    /// `file_path` of their own to anchor on). Shared by `build` (over a
135	    /// fully-merged `GlobalSourceData`) and `merge_file` (over one file's own
136	    /// `SourceData`) — both have the identical flat-map shape.
137	    fn insert_flat_maps(
138	        &mut self,
139	        interfaces: &FxHashMap<std::string::String, CollectedInterface>,
140	        interface_type_params: &FxHashMap<std::string::String, Vec<TypeName>>,
141	        type_aliases: &FxHashMap<std::string::String, CollectedTypeAlias>,
142	        type_alias_params: &FxHashMap<std::string::String, Vec<TypeName>>,
143	        type_param_defaults: &FxHashMap<std::string::String, Vec<Option<CollectedType>>>,
144	    ) {
145	        let maps = std::sync::Arc::make_mut(&mut self.maps);
146	        for (key, defaults) in type_param_defaults {
147	            let Some((file, name)) = key.rsplit_once(':') else { continue };
148	            let file = PathKey::from(Utf8Path::new(file));
149	            maps.type_param_defaults.entry(file).or_default().insert(CompactString::from(name), defaults.clone());
150	        }
151	        for (key, iface) in interfaces {
152	            let Some((file, name)) = key.rsplit_once(':') else { continue };
153	            let file = PathKey::from(Utf8Path::new(file));
154	            if name.starts_with("React.") {
155	                maps.react_namespaced.insert(file.clone());
156	            }
157	            maps.interfaces.entry(file.clone()).or_default().insert(CompactString::from(name), iface.clone());
158	            if let Some(params) = interface_type_params.get(key) {
159	                maps.interface_type_params.entry(file).or_default().insert(CompactString::from(name), params.clone());
160	            }
161	        }
162	
163	        for (key, alias) in type_aliases {
164	            let Some((file, name)) = key.rsplit_once(':') else { continue };
165	            let file = PathKey::from(Utf8Path::new(file));
166	            if name.starts_with("React.") {
167	                maps.react_namespaced.insert(file.clone());
168	            }
169	            maps.type_aliases.entry(file.clone()).or_default().insert(CompactString::from(name), alias.clone());
170	            if let Some(params) = type_alias_params.get(key) {
171	                maps.type_alias_params.entry(file).or_default().insert(CompactString::from(name), params.clone());
172	            }
173	        }
174	    }
175	
176	    fn insert_const_arrays(&mut self, const_arrays: &FxHashMap<std::string::String, Vec<EnumValue>>) {
177	        let maps = std::sync::Arc::make_mut(&mut self.maps);
178	        for (key, values) in const_arrays {
179	            let Some((file, name)) = key.rsplit_once(':') else { continue };
180	            let file = PathKey::from(Utf8Path::new(file));
181	            maps.const_arrays.entry(file).or_default().insert(CompactString::from(name), values.clone());
182	        }
183	    }
184	
185	    /// This index with `fallback` as its dependency layer. The project's declarations are shared, not copied.
186	    pub(crate) fn with_fallback(&self, fallback: std::sync::Arc<NamedTypeIndex>) -> NamedTypeIndex {
187	        NamedTypeIndex { maps: self.maps.clone(), fallback: Some(fallback) }
188	    }
189	
190	    /// Whether `other` shares this index's project declarations, not a copy of them (tests).
191	    #[cfg(test)]
192	    pub(crate) fn shares_declarations_with(&self, other: &NamedTypeIndex) -> bool {
193	        std::sync::Arc::ptr_eq(&self.maps, &other.maps)
194	    }
195	
196	    /// The index holding `file`'s declarations: this one, or the nearest dependency fallback that holds the file (a
197	    /// chain of layers, each holding the files it added). Project and dependency files never overlap, so a file is in
198	    /// exactly one of them; a file no layer holds is answered by the last layer, which finds nothing.
199	    fn layer_for(&self, file: &Utf8Path) -> &NamedTypeIndex {
200	        let mut index = self;
201	        while let Some(fallback) = &index.fallback {
202	            if index.interfaces.contains_key(file.as_str()) || index.type_aliases.contains_key(file.as_str()) {
203	                break;
204	            }
205	            index = fallback;
206	        }
207	        index
208	    }
209	
210	    /// Look up an interface by canonical `(file, name)`, falling back to a
211	    /// `React.`-namespace-qualified name. `@types/react` declares everything
212	    /// inside `declare namespace React { ... }`, so real declarations are
213	    /// keyed "React.HTMLAttributes" even though nothing imports them that
214	    /// way — a plain `import type { HTMLAttributes } from "react"` binds the
215	    /// bare name.
216	    pub(crate) fn lookup_interface(&self, file: &Utf8Path, name: &str) -> Option<&CollectedInterface> {
217	        let index = self.layer_for(file);
218	        let per_file = index.interfaces.get(file.as_str())?;
219	        per_file.get(name).or_else(|| {
220	            index.react_namespaced.contains(file.as_str()).then(|| per_file.get(format!("React.{name}").as_str()))?
221	        })
222	    }
223	
224	    /// Same as `lookup_interface`, for type aliases. Returns the matched name
225	    /// (bare or `React.`-qualified) alongside the value, since callers also
226	    /// need it to look up `type_alias_params` under the same `(file, name)`.
227	    pub(crate) fn lookup_type_alias(
228	        &self,
229	        file: &Utf8Path,
230	        name: &str,
231	    ) -> Option<(CompactString, &CollectedTypeAlias)> {
232	        let index = self.layer_for(file);
233	        let per_file = index.type_aliases.get(file.as_str())?;
234	        if let Some(alias) = per_file.get(name) {
235	            return Some((CompactString::from(name), alias));
236	        }
237	        if !index.react_namespaced.contains(file.as_str()) {
238	            return None;
239	        }
240	        let qualified = format!("React.{name}");
241	        per_file.get(qualified.as_str()).map(|alias| (CompactString::from(qualified), alias))
242	    }
243	
244	    /// The interfaces named `qualified` (`React.HTMLAttributes`) that files other than `react_file` declare into the
245	    /// `React` namespace: `declare module "react" { interface HTMLAttributes<T> { tw?: string } }` merges with React's
246	    /// own, as TypeScript merges it. Every layer is searched and the answer is in file order, so it does not depend
247	    /// on hashing.
248	    pub(crate) fn react_augmentations(&self, react_file: &Utf8Path, qualified: &str) -> Vec<&CollectedInterface> {
249	        let mut found: Vec<&CollectedInterface> = Vec::new();
250	        let react_key = PathKey::from(react_file);
251	        let mut layer = Some(self);
252	        while let Some(index) = layer {
253	            for file in index.react_namespaced.iter().filter(|file| **file != react_key) {
254	                found.extend(index.interfaces.get(file).and_then(|per_file| per_file.get(qualified)));
255	            }
256	            layer = index.fallback.as_deref();
257	        }
258	        found.sort_by(|a, b| a.file_path.cmp(&b.file_path));
259	        found
260	    }
261	
262	    /// The files other than `react_file` that declare into the `React` namespace in any layer, which is every file
263	    /// `react_augmentations` can read from. A resolution that reads augmentations depends on each.
264	    pub(crate) fn react_augmenting_files(&self, react_file: &Utf8Path) -> Vec<&PathKey> {
265	        let react_key = PathKey::from(react_file);
266	        let mut files = Vec::new();
267	        let mut layer = Some(self);
268	        while let Some(index) = layer {
269	            files.extend(index.react_namespaced.iter().filter(|file| **file != react_key));
270	            layer = index.fallback.as_deref();
271	        }
272	        files
273	    }
274	
275	    /// Whether `file`, in this index itself and not its dependency fallback, declares into the `React` namespace.
276	    pub(crate) fn declares_react_namespace(&self, file: &Utf8Path) -> bool {
277	        self.react_namespaced.contains(file.as_str())
278	    }
279	
280	    /// The members of the array-typed const `name` declared at `file`, in this index or the dependency fallback.
281	    pub(crate) fn lookup_const_array(&self, file: &Utf8Path, name: &str) -> Option<&[EnumValue]> {
282	        self.const_arrays
283	            .get(file.as_str())
284	            .and_then(|per_file| per_file.get(name))
285	            .map(Vec::as_slice)
286	            .or_else(|| self.fallback.as_ref()?.lookup_const_array(file, name))
287	    }
288	
289	    /// Whether `name` is actually declared at `file` — mirrors the bare/
290	    /// `React.`-qualified key fallback `lookup_interface`/`lookup_type_alias`
291	    /// use, so a barrel-chain hop is considered "found" by the same rule
292	    /// those lookups do.
293	    pub(crate) fn is_declared_at(&self, file: &Utf8Path, name: &str) -> bool {
294	        self.lookup_interface(file, name).is_some() || self.lookup_type_alias(file, name).is_some()
295	    }
296	
297	    /// The declared defaults of `name`'s type parameters at `file`, when any has one. `name` is the exact key, as
298	    /// `lookup_type_alias` returns it or an interface's `scoped_key` ends.
299	    pub(crate) fn lookup_type_param_defaults(&self, file: &Utf8Path, name: &str) -> Option<&[Option<CollectedType>]> {
