75	fn attribute_from(
76	    root: CollectedType,
77	    name: &str,
78	    react_file: &Utf8Path,
79	    ctx: &ResolutionContext,
80	    state: &mut ResolveState,
81	    depth: u8,
82	) -> Option<ParsedProp> {
83	    // Declared inside `declare namespace React`, so keyed by their qualified names whichever way they are referenced.
84	    let key = |type_name: &str| format!("React.{}", type_name.strip_prefix("React.").unwrap_or(type_name));
