101	                            |ty: &CollectedType| subst.as_ref().map_or_else(|| ty.clone(), |s| substitute_type(ty, s));
102	                        if let Some(raw) = iface.props.iter().find(|prop| prop.name == name) {
103	                            let ty = substituted(&raw.collected_type);
104	                            let prop_type = resolve_collected_type(&ty, &iface.file_path, ctx, state, depth);
105	                            let parent =
106	                                PropParent { name: iface.name.to_string(), file_name: iface.file_path.to_string() };
107	                            return Some(ParsedProp::new(
108	                                name.to_owned(),
109	                                prop_type,
110	                                raw.required,
111	                                None,
112	                                raw.description.clone(),
113	                                raw.tags.clone(),
114	                                Some(parent.clone()),
115	                                vec![parent],
116	                            ));
117	                        }
118	                        pending.extend(iface.extends.iter().map(|extends| {
119	                            let (ExtendsRef::SameFile { name, type_args }
120	                            | ExtendsRef::Imported { local_name: name, type_args, .. }
121	                            | ExtendsRef::Builtin { name, type_args, .. }) = extends;
122	                            CollectedType::Named {
123	                                name: name.clone(),
124	                                args: type_args.iter().map(substituted).collect(),
125	                            }
126	                        }));
127	                    }
128	                } else if let Some(alias) = ctx.react_index().lookup_type_alias_exact(react_file, &key) {
129	                    let alias = match ctx.react_index().lookup_type_alias_params(react_file, &key) {
130	                        Some(params) => {
131	                            substitute_alias(alias, &build_substitution(params, &args, react_file, &mut ignored))
132	                        }
133	                        None => alias.clone(),
134	                    };
135	                    match alias {
136	                        CollectedTypeAlias::Intersection { members, .. } => pending.extend(members),
137	                        CollectedTypeAlias::Passthrough { target, .. } => pending.push_back(target),
138	                        _ => {}
139	                    }
140	                }

